/* 只收录人工确认的构词与词族线索，不按字母相似度自动猜词源。
   kind 区分历史来源、现代构词和词族联想；相关词可包含少量拓展词。
   短语仅通过下面逐条列出的别名关联，不进行模糊包含匹配。 */
const RootMemory=(()=>{
  const records=new Map(),known=new Set(VOCAB.map(w=>w.id));
  const normalize=value=>String(value??'').toLocaleLowerCase('it').normalize('NFC').replace(/[’‘]/g,"'").trim();
  function add(ids,kind,title,explanation,related,lemma){
    const item=Object.freeze({kind,title,explanation,related:Object.freeze(related.map(([it,zh])=>Object.freeze({it,zh}))),source:Object.freeze({title:'Treccani：'+lemma,url:'https://www.treccani.it/vocabolario/'+encodeURIComponent(lemma)+'/'})});
    ids.split('|').forEach(raw=>{const id=normalize(raw);if(!known.has(id))throw Error('词根记忆引用不存在的词：'+id);if(records.has(id))throw Error('词根记忆重复：'+id);records.set(id,item)});
  }
  add('vedere|vista sul mare','历史词根','ved- / vid- / vis-：看','vedere 来自拉丁语 videre；其词族还有 visto 和 visione。可以把这几种词干一起记，但不能把 vedere 硬拆成 vis 加上其他字母。短语 vista sul mare 中的 vista 是“景观、视野”。',[['vedere','看见'],['visto','看见过；vedere 的过去分词'],['visione','视觉；观看']],'vedere');
  add('televisore','历史词根','tele-：远；vis-：看','televisore 与 televisione 相连：tele- 表示远距离，vis- 属于“看”的词族。记成“远处的画面传过来”，即电视机；不是把结尾 -ore 单独翻成“人”。',[['televisione','电视；电视传播'],['visione','视觉；观看']],'televisore');
  add('scrivere|ti scrivo per','历史词根','scriv- / scritt-：写','scrivere 来自拉丁语 scribere。现在时 scrivo 与过去分词 scritto 看起来不同，却是同一动词的词干变化。ti scrivo per… 就是“我写信给你是为了……”。',[['scrivere','写'],['scrivo','我写'],['scritto','写过的；写的过去分词']],'scrivere');
  add('iscriversi','历史词根','iscriv-：把名字写入名单','iscrivere 的历史来源是“写入”；反身形式 iscriversi 表示为自己登记、报名。把“名字写进课程名单”连到“报名”上记。这里的 i- 不能解释成表示否定的 in-。',[['scrivere','写'],['iscrizione','报名；登记'],['iscritto','已报名的']],'iscrivere');
  add('libro|libreria|in libreria|dei libri','构词法','libr-：书；-eria：相关营业场所','libro 的词干 libr- 可以在 libreria 中认出来：与书有关的店，即书店；libreria 也能指书架。-eria 常用于场所名，但不能看到同样结尾就认定都是商店。',[['libro','书'],['libreria','书店；书架']],'libreria');
  add('pane|panino|panificio|panino al prosciutto|del pane','构词法','pan-：面包','pane、panino、panificio 都能连到“面包”这条词族线上。panino 原有“小面包”的构词关系，日常也指夹馅面包；panificio 是制作或销售面包的地方。',[['pane','面包'],['panino','小面包；三明治'],['panificio','面包房']],'panificio');
  add('gelato|gelateria','构词法','gelat-：冰淇淋；-eria：店','先记 gelato，再把 gelateria 当作“卖 gelato 的地方”。这里的 -eria 帮你从商品名走到店名，不需要给 gelato 的每个音节另编意思。',[['gelato','冰淇淋'],['gelateria','冰淇淋店']],'gelateria');
  add('pesce|pescheria','构词法','pesc-：鱼；-eria：店','pesce 是鱼，pescheria 是鱼店。pesce 的 sce 与 pescheria 的 sche 读音不同；后者 sch 发 [sk]。词族中会有拼写与音变，不要因为多了 h 就把它当作另一条词根。',[['pesce','鱼'],['pescheria','鱼店；鱼市']],'pescheria');
  add('pasticceria','同族词联想','pasticc-：糕点这一家','把 pasticceria（糕点店）和 pasticcere（糕点师）、pasticcino（小甜点）一起记。它不是“pasta 加 -eria”这样直接拼出来的，别省掉中间的构词变化。',[['pasticcere','糕点师'],['pasticcino','小甜点'],['pasticceria','糕点店']],'pasticceria');
  add('cartoleria|carta igienica|carta d’imbarco','同族词联想','cart-：纸与纸制品','carta 是纸，cartoleria 是文具店，属于与纸、文具相关的词族。carta igienica 是卫生纸；carta d’imbarco 是登机牌。短语含义还要结合后面的修饰语。',[['carta','纸；卡；证件'],['cartoleria','文具店']],'cartoleria');
  add('frutta|fruttivendolo','构词法','frutti- + vend-：水果 + 卖','fruttivendolo 里可以认出“水果”和“卖”的成分，用“卖水果的人”记住水果商。它也可以指水果店；不是泛指所有商店。',[['frutta','水果'],['vendere','卖'],['fruttivendolo','水果商；水果店']],'fruttivendolo');
  add('biblioteca|in biblioteca','历史词根','biblio-：书；-teca：收藏处','biblioteca 的来源包含希腊语中“书”和“存放处”的成分，连起来记成“存放书、供人阅读的地方”，即图书馆。它与卖书的 libreria 用法不同。',[['biblioteca','图书馆'],['bibliotecario','图书管理员']],'biblioteca');
  add('discoteca|in discoteca','构词法','disco + -teca：唱片的收藏处','disco 是唱片；discoteca 原可表示唱片收藏，后来也表示播放舞曲、供人跳舞的场所。和 biblioteca 的 -teca 连起来记“收藏处”，再记住它的日常场所义。',[['disco','唱片；圆盘'],['discoteca','迪斯科舞厅；唱片收藏']],'discoteca');
  add('enoteca','历史词根','eno-：葡萄酒；-teca：收藏处','eno- 是与葡萄酒有关的希腊语来源构词成分；enoteca 可以记成“收藏、销售或品尝葡萄酒的地方”。eno- 不是意大利语普通单词 vino 的随意缩写。',[['enoteca','葡萄酒商店；酒窖'],['enologia','葡萄酒酿造学']],'enoteca');
  add('telefono|telefonare','历史词根','tele-：远；-fono：声音','telefono 的构词成分表示“远处的声音”，用来记电话；telefonare 是相关动词“打电话”。不要把 -fono 和 fotografia 中的 foto- 混在一起。',[['telefono','电话'],['telefonare','打电话'],['microfono','麦克风']],'telefono');
  add('fotografia','历史词根','foto-：光；-grafia：记录、描绘','摄影可以想成“用光记录图像”。fotografia 经其他欧洲语言传入意大利语，构词成分最终来自希腊语；这里的 foto- 不是表示声音的 -fono。',[['fotografia','摄影；照片'],['fotografo','摄影师']],'fotografia');
  add('xilofono','历史词根','xilo-：木；-fono：声音','xilofono 是木琴：木制音条发出声音。用 xilo- 与 -fono 两部分记，比把外来字母 x 单独翻成某种意思更可靠。',[['xilofono','木琴'],['telefono','电话'],['microfono','麦克风']],'xilofono');
  add('filosofia','历史词根','filo-：喜爱；sofia：智慧','filosofia 的古希腊语构词含义是“爱智慧”，由此记住“哲学”。这说明历史构词关系，不是说现代意大利语里 sofia 可以单独替代“智慧”。',[['filosofia','哲学'],['filosofo','哲学家']],'filosofia');
  add('automobile|mobile','历史词根','auto-：自己；mobile：能移动的','automobile 可用“自己能移动的车辆”来记；mobile 的历史核心是“能移动的”。但作为名词 un mobile，在本课语境里是“一件家具”，不是手机。',[['automobile','汽车'],['mobile','可移动的；一件家具'],['mobili','家具（复数）']],'automobile');
  add('moto|motocicletta','同族词联想','moto 是 motocicletta 的简称','motocicletta 属于与 motore（发动机）和两轮车辆相关的词族。日常把 motocicletta 缩成 moto；不要把 moto 的每个音节分别硬译成中文。',[['motore','发动机'],['motocicletta','摩托车'],['moto','摩托车（简称）']],'motocicletta');
  add('bicicletta|bici','历史词根','bi-：两个；cicl-：轮、循环','bicicletta 经法语而来，可以借“两只轮子”的构词线索记自行车。bici 是它的常用简称；-etta 在这个固定词里不必单独译成“小”。',[['bicicletta','自行车'],['bici','自行车（简称）'],['ciclista','骑自行车的人']],'bicicletta');
  add('metropolitana|metro','同族词联想','metro 是 metropolitana 的简称','意大利语地铁常说 la metropolitana，也常缩成 la metro。把两个形式成对记；这个缩写不能解释成“地铁只有一米长”，也别和计量单位 metro 混淆。',[['metropolitana','地铁'],['metro','地铁（简称）；米（另一用法）']],'metropolitana');
  add('aereo|aeroporto|in aeroporto','历史词根','aero-：空气、航空；porto：港口','aeroporto 是“航空的港口”，即机场；aereo 则是飞机，也可作形容词表示航空的。用“空港”的中文概念连接这组词。',[['aereo','飞机'],['aeroporto','机场'],['porto','港口']],'aeroporto');
  add('ipermercato','构词法','iper-：超；mercato：市场','iper- 表示超出普通规模，mercato 是市场；ipermercato 因而是规模很大的综合卖场。记“超大型市场”，不要把 iper- 当作随意省写的 in。',[['mercato','市场'],['supermercato','超市'],['ipermercato','大型综合超市']],'ipermercato');
  add('microonde','构词法','micro-：微小；onde：波','microonde 可指微波，也常在日常语境里指微波炉（forno a microonde 的简称）。记 micro- + onde；onde 是 onda 的复数。',[['onda','波'],['microonde','微波；微波炉'],['forno a microonde','微波炉']],'microonde');
  add('neonato|nascere|nascita','同族词联想','nasc- / nat-：出生','nascere 是出生，nascita 是出生这件事，nato 是 nascere 的过去分词。neonato 中 neo- 表示新，整体就是“刚出生的孩子”；nat- 不是一个随便接在所有词后的出生后缀。',[['nascere','出生'],['nato','出生的'],['neonato','新生儿']],'neonato');
  add('mezzogiorno|mezzanotte|mezzo|e mezzo','构词法','mezzo：一半、中间','mezzogiorno 把“中间”连到 giorno（白天），记作中午；mezzanotte 是夜的中间，即午夜。e mezzo 在钟点中表示“又半个小时”；词形还要配合具体表达。',[['mezzogiorno','中午'],['mezzanotte','午夜'],['mezzo','一半；中间的']],'mezzogiorno');
  add('capodanno','构词法','capo d’anno：一年的开头','capo 除了“头”也可表示开头，anno 是年。把 capo d’anno 连成 capodanno，就能记住元旦、新年第一天。',[['capo','头；首领；开头'],['anno','年'],['Capodanno','元旦']],'capodanno');
  add('apribottiglia|aprire|bottiglia','构词法','apri- + bottiglia：开 + 瓶子','apribottiglia 是动词与名词组成的工具名：“打开瓶子的东西”就是开瓶器。这里 apri 来自 aprire；同类工具词通常要整体记住性数用法。',[['aprire','打开'],['bottiglia','瓶子'],['apribottiglia','开瓶器']],'apribottiglia');
  add('lavare|lavarsi|lavatrice|lavastoviglie|lavandino','同族词联想','lav-：洗','先记 lavare（洗），再连到 lavarsi（洗自己）、lavatrice（洗衣机）、lavandino（洗手池）。lavastoviglie 中 stoviglie 是餐具，因此它是洗碗机，不是洗衣机。',[['lavare','洗'],['lavatrice','洗衣机'],['lavastoviglie','洗碗机'],['lavandino','洗手池']],'lavare');
  add('asciugamano|asciugacapelli','构词法','asciuga-：弄干；看后面弄干什么','asciugare 是弄干。asciugamano 用来擦干手，因此是毛巾；asciugacapelli 用来弄干头发，因此是吹风机。把工具的动作和对象一起记。',[['asciugare','弄干'],['asciugamano','毛巾'],['asciugacapelli','吹风机']],'asciugamano');
  add('aspirapolvere','构词法','aspira- + polvere：吸 + 灰尘','aspirare 有吸入的意思，polvere 是灰尘。“吸灰尘的工具”就是 aspirapolvere。这里是可理解的现代合成词，不需要另外发明拉丁词根。',[['aspirare','吸入'],['polvere','灰尘'],['aspirapolvere','吸尘器']],'aspirapolvere');
  add('pallacanestro|canestro|palla','构词法','palla + canestro：球 + 篮','palla 是球，canestro 是篮筐；把球投入篮筐的运动就是 pallacanestro。词义落在篮球运动，不是任意一个装球的篮子。',[['palla','球'],['canestro','篮；篮球的篮筐'],['pallacanestro','篮球运动']],'pallacanestro');
  add('pallavolo|volo|volare','构词法','palla + volo：球 + 飞','volo 是飞行，与 volare（飞）相连。pallavolo 把“球”和“飞”组合成排球这一运动名称；记画面有帮助，但它的固定词义是排球。',[['volare','飞'],['volo','飞行；航班'],['pallavolo','排球']],'pallavolo');
  add('frigorifero|frigobar','历史词根','frigor-：冷；-fero：带来','frigorifero 的来源包含拉丁语“冷”的词干和“带来”的构词成分，可记成“产生冷的设备”。frigobar 与它同属制冷词族，日常是迷你冰箱。',[['frigorifero','冰箱'],['frigobar','迷你冰箱'],['frigo','冰箱（简称）']],'frigorifero');
  add('calorifero','历史词根','calor-：热；-fero：带来','calorifero 的来源可联系“热”与“带来”：带来热量的设备，即暖气设备。它与 frigorifero 的 -fero 相呼应，一个供热、一个制冷。',[['calore','热；热量'],['calorifero','暖气设备'],['frigorifero','冰箱']],'calorifero');
  add('termosifone','历史词根','termo-：热','termosifone 中 termo- 表示热，后半部分与 sifone（虹吸管）有关。先用“热的循环装置”连接暖气片这个日常词义；不要把 -sifone 误说成“声音”。',[['termometro','温度计'],['termosifone','暖气片；热虹吸装置']],'termosifone');
  add('finestra|finestrino','构词法','finestr-：窗；-ino：较小的','finestrino 与 finestra 属同族，可借“小窗”来记车窗、舷窗等常用意义。-ino 常可构成小称，但具体词义要按使用场景记。',[['finestra','窗户'],['finestrino','车窗；小窗']],'finestrino');
  add('tavolo|tavolino','构词法','tavol-：桌；-ino：小称','tavolo 是桌子，tavolino 是小桌、茶几。先抓住 tavol-，再用 -ino 的小称线索区分大小；-ino 并不是所有词里都表示小。',[['tavolo','桌子'],['tavolino','小桌；茶几']],'tavolino');
  add('scarpa|scarpiera','构词法','scarp-：鞋；-iera：容纳相关物品的东西','scarpa 是鞋，scarpiera 是放鞋的柜架。把“鞋的收纳处”这个画面连起来；-iera 在别的词里还可有其他构词用途。',[['scarpa','鞋'],['scarpiera','鞋柜；鞋架']],'scarpiera');
  add('forno|fornello','同族词联想','forn-：炉具这一家','forno 是烤箱、炉，fornello 常指灶头、小炉。它们有构词关系，却不代表可以在做饭说明中随意互换。',[['forno','烤箱；炉'],['fornello','灶头；小炉']],'fornello');
  add('ombra|ombrello','历史词根','ombr-：阴影','ombrello 的历史构词与 ombra（阴影）有关，可先想遮阳形成的阴影，再记现代常见词义“伞”。现代使用时它也能是雨伞，不只遮阳。',[['ombra','阴影'],['ombrello','伞']],'ombrello');
  add('sedia|sedile|sedersi','同族词联想','sed-：坐','sedersi 是坐下，sedia 是椅子，sedile 是座位。把“坐”这条词族线连接起来；它们不是简单地把 -ia、-ile 都当同一种后缀。',[['sedersi','坐下'],['sedia','椅子'],['sedile','座位']],'sedile');
  add('cantare|cantante','构词法','cant-：唱；cantante：唱歌的人','cantare 是唱歌，cantante 是歌手。cantante 来自动词的现在分词形式，用作名词表示从事这件事的人。别把“歌手”理解成过去已经唱完的人。',[['cantare','唱歌'],['cantante','歌手'],['canto','歌唱；歌']],'cantante');
  add('studiare|studio|studente|studentessa','同族词联想','stud-：学习、用功','studiare 是学习，studio 可指学习、书房或工作室；studente/studentessa 是学生。把学习的人、行为和场所连起来记；这些词的结尾还承担不同词类和性别功能。',[['studiare','学习'],['studio','学习；书房；工作室'],['studente','学生'],['studentessa','女学生']],'studente');
  add('lavoro|lavorare|al lavoro|festa del lavoro|giorno lavorativo','同族词联想','lavor-：工作','lavoro 是工作，lavorare 是工作这一动作，lavorativo 表示与工作有关。al lavoro 是在工作、去工作的常用短语；把词族线索和整块搭配一起记。',[['lavoro','工作'],['lavorare','工作'],['lavorativo','工作的；工作日的']],'lavorare');
  add('cucina|cucinare','构词法','cucin-：厨房、烹饪','cucina 可以指厨房或烹饪，cucinare 是做饭。先把人在 cucina 做饭的场景想清楚，再区分名词和动词。',[['cucina','厨房；烹饪'],['cucinare','做饭']],'cucinare');
  add('pranzo|pranzare|a pranzo','构词法','pranz-：午饭','pranzo 是午饭，pranzare 是吃午饭。a pranzo 是吃午饭时、去吃午饭的常用搭配；词根提示不能代替对介词搭配的记忆。',[['pranzo','午饭'],['pranzare','吃午饭'],['a pranzo','吃午饭时；去吃午饭']],'pranzare');
  add('domanda|domandare','构词法','domand-：问','domanda 是问题、询问，domandare 是询问的动作。用“一个问题”和“提出问题”连接词义；domanda 在申请情境里也能指申请。',[['domanda','问题；申请'],['domandare','询问；要求']],'domandare');
  add('viaggio|viaggiare|buon viaggio','构词法','viagg-：旅行','viaggio 是旅行，viaggiare 是旅行这一动作；构词后保留 gi 的软音拼写。Buon viaggio! 是祝一路顺风的整句表达。',[['viaggio','旅行'],['viaggiare','旅行'],['buon viaggio','一路顺风']],'viaggiare');
  add('parcheggio|parcheggiare','同族词联想','parchegg-：停车','parcheggiare 是停车，parcheggio 是停车场，也能指停车这个行为。把停汽车的动作与地点放进一个场景中记。',[['parcheggiare','停车'],['parcheggio','停车场；停车']],'parcheggiare');
  add('racconto|raccontare','同族词联想','raccont-：讲述','racconto 是故事、叙述；raccontare 是讲故事、讲述。用“故事”和“讲故事”的动作关系记住词族。Racconto una storia. 表示“我讲一个故事”。',[['racconto','故事；叙述'],['raccontare','讲述']],'raccontare');
  add('prenotare|prenotazione','构词法','pre-：预先；not-：记下','prenotare 可借“预先记下、登记”来记预订；prenotazione 是预订这一行为或记录。-zione 常构成动作名词，但不能把所有 -zione 词都机械还原成一个现代动词。',[['prenotare','预订'],['prenotazione','预订；预约']],'prenotare');
  add('dormire|addormentarsi','同族词联想','dorm-：睡；addormentarsi：进入睡眠','dormire 是睡觉，addormentarsi 是睡着、进入睡眠。用状态与进入状态的区别记；addormentarsi 不是“又睡一次”，不能把开头误认成 ri-。',[['dormire','睡觉'],['addormentarsi','睡着'],['dormitorio','宿舍']],'addormentare');
  add('sveglia|svegliarsi','同族词联想','svegli-：醒来','svegliarsi 是醒来，la sveglia 是闹钟，也可指起床信号。把闹钟使人醒来的场景连起来记；这里的 s- 不宜单独套用成“否定”。',[['svegliarsi','醒来'],['sveglia','闹钟'],['sveglio','醒着的；机灵的']],'sveglia');
  add('vestito|vestirsi|travestirsi','同族词联想','vest-：衣服、穿衣','vestito 是衣服或穿好的；vestirsi 是给自己穿衣，travestirsi 是乔装、化装。先抓住 vest- 的衣着联系，tra- 在这个固定词里的作用不能套成常见介词“在……之间”。',[['vestito','衣服；穿着的'],['vestirsi','穿衣'],['travestirsi','乔装；化装']],'travestire');
  add('comodo|scomodo','构词法','s- 可表示相反：comodo → scomodo','comodo 是舒适、方便的；加上这里表示反义的 s-，成为不舒适、不方便的 scomodo。这个前缀功能要逐词确认，不代表所有 s 开头的词都是否定。',[['comodo','舒适的；方便的'],['scomodo','不舒适的；不方便的']],'scomodo');
  add('piacere|mi piace|mi piacciono|mi dispiace|il piacere è mio','同族词联想','piac-：使人愉快；dispiacere：使人遗憾','piacere 是使人喜欢、愉快，dispiacere 则可表示使人遗憾。Mi dispiace 常用来表达遗憾或道歉，不能逐字当作普通的“我不喜欢”。mi piace/piacciono 仍要按后面被喜欢的事物配合。',[['piacere','使人喜欢；愉快'],['dispiacere','使人遗憾'],['mi dispiace','我很遗憾；对不起']],'dispiacere');
  add('entrare|rientrare','构词法','ri-：回来、再次；entrare：进入','entrare 是进入，rientrare 是回到里面、返回。用“第一次进去”和“回去”区分；ri- 在其他词里也可能有强化等作用，不是一律表示再次。',[['entrare','进入'],['rientrare','回来；回到里面']],'rientrare');
  add('tornare|ritornare','构词法','ri- + tornare：再次回来、返回','tornare 本来已有返回的意思，ritornare 常与它近义，有时更突出再次或回转。不要为了拆词把 tornare 误教成“只往前去”。',[['tornare','回来；返回'],['ritornare','回来；再次返回']],'ritornare');
  add('chiedere|richiedere','历史词根','chied-：问、要求；ri- 不总是“再”','richiedere 与 chiedere 属同族，历史上含 re-。它可以表示再问，也常表示正式地要求、申请或需要，不能看到 ri- 就把整词固定译为“再问”。',[['chiedere','问；请求'],['richiedere','要求；申请；需要'],['richiesta','请求；申请']],'richiedere');
  add('vecchio|invecchiare','构词法','vecchi-：老；invecchiare：变老','从形容词 vecchio 连到动词 invecchiare，记“变得老”。这里 in- 参与构成变化动词，并不表示“不老”。',[['vecchio','老的；旧的'],['invecchiare','变老；使变老']],'invecchiare');
  add('giovane|ringiovanire','构词法','giovan-：年轻；ringiovanire：恢复年轻','giovane 是年轻的；ringiovanire 的构词使它表示重新变年轻、使显年轻。抓住 giovan-，同时记住动词按 -isc- 型变化：ringiovanisco。',[['giovane','年轻的；年轻人'],['ringiovanire','变年轻；使年轻']],'ringiovanire');
  add('dimagrire','构词法','magr-：瘦；dimagrire：变瘦','magro 是瘦的；dimagrire 表示变瘦、减轻体重。用形容词和变化动作一起记。不要把 di- 当成一个能自动翻译成“减少”的万能前缀。',[['magro','瘦的'],['dimagrire','变瘦；减肥']],'dimagrire');
  add('ingrassare','构词法','grass-：胖、脂肪；ingrassare：变胖','grasso 是胖的，也可指脂肪；ingrassare 可以表示变胖。这里 in- 参与构成变化动词，不是否定前缀。',[['grasso','胖的；脂肪'],['ingrassare','变胖；使肥胖']],'ingrassare');
  add('nebbia|nebbioso','构词法','nebbi-：雾；-oso：有这种特征的','nebbia 是雾；nebbioso 表示有雾的。-oso 常把名词变成“有、充满某种特征”的形容词，nebbioso 就可以记成雾很多的。',[['nebbia','雾'],['nebbioso','有雾的']],'nebbioso');
  add('nuvola|nuvoloso','构词法','nuvol-：云；-oso：有这种特征的','nuvola 是云，nuvoloso 是多云的。把云的名词与天气的形容词连接起来；词尾 -o 仍需要随描述对象配合。',[['nuvola','云'],['nuvoloso','多云的']],'nuvoloso');
  add('vento|ventoso','构词法','vent-：风；-oso：有这种特征的','vento 是风；ventoso 是有风、多风的。不要把 vento 的这条词干与数字 venti（二十）仅因拼写近似就混为同根。',[['vento','风'],['ventoso','多风的']],'ventoso');
  add('pioggia|piovere|piovoso','同族词联想','piogg- / piov-：雨','pioggia 是雨，piovere 是下雨，piovoso 是多雨的。词干形式会变化，先用“雨—下雨—多雨”的语义链记，不要硬找每个字母都相同的部分。',[['pioggia','雨'],['piovere','下雨'],['piovoso','多雨的']],'piovoso');
  add('neve|nevicare','同族词联想','nev-：雪','neve 是雪，nevicare 是下雪。用名词与天气动作连接记忆；平常说“下雪了”会见到 nevica，不必带一个表示人的主语。',[['neve','雪'],['nevicare','下雪']],'nevicare');
  add('sole|soleggiato','同族词联想','sol-：太阳','sole 是太阳，soleggiato 是阳光充足的。通过“有太阳照着”的场景记住 soleggiato；日常天气语境里不是指有很多个太阳。',[['sole','太阳'],['soleggiato','阳光充足的'],['solare','太阳的']],'soleggiato');
  add('stellato','构词法','stell-：星；-ato：具有这种特征的','stella 是星星，stellato 表示有星的、星光灿烂的。想象 un cielo stellato（繁星满天的天空）；-ato 在这个词里构成形容词，不表示某人完成了“星星”这个动作。',[['stella','星星'],['stellato','有星的；星光灿烂的']],'stellato');
  add('luce|luminoso','历史词根','luc- / lumin-：光','luce 与 luminoso 都属于“光”的历史词族，词干形式有差别。luminoso 表示明亮的、有光的；不要把它的前几字母生搬到所有 lu- 开头的词上。',[['luce','光'],['luminoso','明亮的'],['illuminare','照亮']],'luminoso');
  add('rumoroso','构词法','rumor-：噪声；-oso：有这种特征的','rumore 是声音、噪声，rumoroso 表示吵闹的。由名词到形容词记“有很多噪声”，而不是把整词只记成抽象的“坏”。',[['rumore','声音；噪声'],['rumoroso','吵闹的']],'rumoroso');
  add('silenzioso','构词法','silenzi-：安静；-oso：有这种特征的','silenzio 是安静、沉默；silenzioso 是安静的、沉默的。-oso 在这里表示具有这种状态，不一定表示某种可数物品很多。',[['silenzio','安静；沉默'],['silenzioso','安静的；沉默的']],'silenzioso');
  add('famoso','历史词根','fam-：声誉；-oso：具有这种特征的','famoso 的词族包含 fama（名声），可用“有名声的”记著名的。不要把 fam- 与 fame（饥饿）因为字母相近就认成同义。',[['fama','名声'],['famoso','著名的'],['fame','饥饿（不要混淆）']],'famoso');
  add('vero|veramente','构词法','ver-：真；-mente：构成副词','vero 是真的，veramente 是真正地、确实。构成副词时用 vera + -mente；这里展示的是现代构词，不把 -mente 当成新的“真”的词根。',[['vero','真的'],['veramente','真正地；确实']],'veramente');
  add('raramente','构词法','rara + -mente：很少地','raro 是罕见的，取形式 rara 再加 -mente 得到 raramente，表示很少、难得。把频率低这个意思和形容词 raro 一起记。',[['raro','罕见的；稀少的'],['raramente','很少；难得']],'raramente');
  add('generalmente','构词法','general- + -mente：一般地','generale 与一般、总体有关；generalmente 表示一般地、通常。generale 的末尾 -e 在 -mente 前脱落，不是把原词完整照抄后再加后缀。',[['generale','一般的；总体的'],['generalmente','一般地；通常']],'generalmente');
  add('fisicamente','构词法','fisica + -mente：在身体方面','fisico 可以表示身体的；fisicamente 可表示在身体方面、体力上。-ico 型形容词形成这类副词时用 -icamente，别写成 fisicomente。',[['fisico','身体的；物理的'],['fisicamente','在身体方面；体力上']],'fisicamente');
  add('attualmente','构词法','attual- + -mente：目前','attuale 是目前的；attualmente 是目前、当前。它和英语 actually 的常用意义不同，不要凭外形记成“事实上”。',[['attuale','目前的'],['attualmente','目前；当前']],'attualmente');
  add('fine|finire','同族词联想','fin-：结束、界限','fine 常指结束，finire 是结束、完成。记住 un film finisce（电影结束）这个动作联系；fine 在不同性别、语境下还能有其他词义，不能只套一个中文义。',[['fine','结束；末尾'],['finire','结束；完成'],['finale','最后的；结局']],'finire');
  add('migliore|migliorare','构词法','miglior-：更好','migliore 是更好的，migliorare 是改善、变好。把“更好”转成“使……更好”的动作来记；migliore 本身已经有比较意义。',[['migliore','更好的'],['migliorare','改善；变好']],'migliorare');
  add('ritardo|ritardare|tardo','同族词联想','tard-：晚、迟','tardo 与晚、迟有关；ritardo 是迟到、延误，ritardare 是延迟或晚到。这里 ri- 不能机械译成“再”，要记住整个词的常用含义。',[['tardo','晚的；迟的'],['ritardo','延误；迟到'],['ritardare','延迟；迟到']],'ritardare');
  add('sci|sciare','构词法','sci → sciare：从滑雪板到滑雪','sci 指滑雪板，也用于滑雪运动；sciare 是滑雪的动作。用器具或运动名称派生动词的关系记忆，sci- 在这里不是表示科学的英语缩写。',[['sci','滑雪板；滑雪'],['sciare','滑雪'],['sciatore','滑雪者']],'sciare');
  add('giorno|giornale|ogni giorno|tutti i giorni','同族词联想','giorn-：日、天','giorno 是一天；giornale 的历史构词与每日有关，日常常指报纸。用“每天出的报纸”连接这组词；ogni giorno 和 tutti i giorni 都可表示每天。',[['giorno','一天；白天'],['giornale','报纸；日志'],['giornaliero','每日的']],'giornale');
  add('notte|pernottare','历史词根','nott- / noct-：夜','pernottare 的历史构词包含表示穿过、度过的 per- 和“夜”的词干，可记成“度过一夜”。普通意大利语 notte 与这里的 nott- 相连。',[['notte','夜晚'],['pernottare','过夜；住宿'],['pernottamento','住宿；过夜']],'pernottare');
  add('scoprire','构词法','s- + coprire：把覆盖去掉','coprire 是覆盖，scoprire 是揭开、发现。先想“去掉遮盖，所以看到了”，再连到抽象的发现。这里的 s- 表示相反、去除。',[['coprire','覆盖'],['scoprire','揭开；发现'],['scoperta','发现']],'scoprire');
  add('indossare','构词法','doss-：背、身上','indossare 与 dosso（背、身上）有关，可以记成把衣服放到身上，即穿上或穿着。它不是 in + 一个表示“衣服”的 dosso，也不能一律只译为已经穿完。',[['dosso','背；身上'],['indosso','在身上'],['indossare','穿上；穿着']],'indossare');
  add('ascensore','历史词根','ascens-：上升','ascensore 的历史来源与拉丁语 ascendere（上升）有关，可用“把人往上送的设备”记电梯。现代电梯当然也会下降，记忆线索不限制实际功能。',[['ascendere','上升'],['ascensore','电梯']],'ascensore');
  add('giurisprudenza','历史词根','giur-：法；prudenza：知识、审慎','giurisprudenza 的拉丁语来源表示法律知识。可以抓住 giur- 与法律的联系，记住它在大学专业语境中的“法学”；不要按普通 prudenza 生硬译成“谨慎地起诉”。',[['giuridico','法律的'],['giurisprudenza','法学；判例法']],'giurisprudenza');
  add('dente','同族词联想','dent-：牙','dente 是牙，dentista 是牙医。用“牙 → 牙医”连接这条词族线；-ista 常表示从事某种活动的人，但并非所有职业都能随意加它来造词。',[['dente','牙'],['dentista','牙医'],['dentale','牙齿的']],'dentista');
  add('mano','同族词联想','man-：手','mano 是手，manuale 可以表示手工的、用手操作的。把手的动作与手工联系起来；不要把所有 man- 开头的词都归进这条词族。',[['mano','手'],['manuale','手工的；手册']],'manuale');
  add('occhiali','构词法','occhi-：眼睛','occhio 是眼睛，occhiali 是眼镜。用“戴在眼睛前的东西”记忆；眼镜这个物品通常用复数 gli occhiali，不能仅凭一副就改成普通单数。',[['occhio','眼睛'],['occhiali','眼镜'],['oculista','眼科医生']],'occhiali');
  add('acqua|dell’acqua','同族词联想','acqu-：水','acqua 是水，acquatico 是水生的、与水有关的。把 acqu- 作为词族线索；acqua 里的 cq 拼写要一起记，不能因为发音近似就省掉 c。',[['acqua','水'],['acquatico','水生的；水的'],['acquario','水族箱；水族馆']],'acquatico');
  add('cuore','历史词根','cuor- / cord-：心','cuore 与 cordiale 的历史词族都连到拉丁语的“心”。可用“发自内心”记住 cordiale（热情、亲切的）；现代拼写并不是在 cuore 后直接加上 -iale。',[['cuore','心'],['cordiale','热情的；亲切的']],'cordiale');
  return Object.freeze({get(id){return records.get(normalize(id))||null},get count(){return records.size}});
})();
